1	import { sep } from 'node:path';
2	import { fileURLToPath } from 'node:url';
3	import { realpathSync } from 'node:fs';
4	import { finding } from '../../../engine/checks/helpers/findings.mjs';
5	import { runRule } from '../../../engine/checks/helpers/work.mjs';
6	import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
7	import { LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR } from '../../../engine/pack_loader/pack-registry.mjs';
8	
9	// The write-surface gate for the growth lifecycle's two CAPTURE runs — extract
10	// and dedup. Their docs bound every edit to the repo's own local packs, and
11	// extract's PR auto-merges with no human review, so the boundary needs a
12	// machine guarantee, not a prose request: when a branch carries one of those
13	// runs' pinned commit subjects, every path it touches — added, modified, or
14	// deleted — must sit under .claudinite/local/packs/ (the legacy
15	// .claudinite/local_packs/ accepted during the rename window).
16	//
17	// The trigger is the run's whole pinned title, NOT the bare "Claudinite growth:"
18	// prefix the whole lifecycle shares, because its other runs have wider surfaces
19	// by design: promote writes the canon under packs/ and skills/ (its own gate is
20	// canon-curation's promote-scope.mjs), and pack discovery writes the repo-root
21	// .claudinite-settings.json declaration that activates the pack it authors.
22	// Keying on the prefix would red both. A run whose title this list doesn't
23	// carry is simply not this rule's business.
24	//
25	// Sibling of that promote-scope gate. Promote can't self-gate — nothing in a
26	// diff marks it as a promote run, so CI keys on its branch prefix — but a
27	// capture run marks ITSELF via its title, so this rule self-gates and runs
28	// everywhere the pack is active: at the session Stop hook (work scope), and as
29	// a CLI on every PR in the canon repo's CI.
30	//
31	// Local packs live under either root during the rename transition; git emits
32	// '/'-separated paths, so the platform-joined constants are normalized.
33	const LOCAL_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
34	  .map((s) => `${s.split(sep).join('/')}/`);
35	
36	// The capture runs, by the exact titles their task docs pin. `conversation
37	// extract` is the pre-merge title of extract's conversation half, still in use
38	// wherever a consumer mounts a canon older than the one-task merge.
39	const CAPTURE_RUN = /^Claudinite growth: (?:extract lessons|conversation extract|dedup\b)/;
40	
41	const inSurface = (p) => LOCAL_ROOTS.some((root) => p.startsWith(root));
42	
43	const rule = {
44	  id: 'growth-write-scope',
45	  severity: 'blocking',
46	  scope: 'work',
47	  doc: 'packs/claudinite-growth/README.md',
48	  description: 'A growth capture run (extract, dedup) writes only the repo\'s own local packs',
49	  why: 'extract auto-merges its PR with no human review and dedup runs unattended; a capture run improves the repo\'s packs, so a write outside .claudinite/local/packs/ — the canon it prunes against, or the project\'s own code — escapes the review-by-blast-radius boundary the growth lifecycle is built on',
50	
51	  run(work) {
52	    if (work.onDefaultBranch()) return [];
53	    if (!work.commits.some((m) => CAPTURE_RUN.test(m))) return [];
54	    const touched = [...new Set([...work.changedFiles, ...work.deleted])];
55	    return touched
56	      .filter((p) => !inSurface(p))
57	      .sort()
58	      .map((p) => finding(rule, {
59	        file: p,
60	        what: `a growth capture run touched ${p}, outside ${LOCAL_ROOTS[0]}`,
