91	diff --git a/packs/claudinite-dashboard/fleet-sweep.mjs b/packs/claudinite-dashboard/fleet-sweep.mjs
92	new file mode 100644
93	index 0000000..f7d506e
94	--- /dev/null
95	+++ b/packs/claudinite-dashboard/fleet-sweep.mjs
96	@@ -0,0 +1,82 @@
97	+// The order a fleet sweep reads in. Pure: no clock, no I/O, no DOM — the callers
98	+// supply what each pass does, this decides who it happens to and when.
99	+//
100	+// A fleet page is read on ONE viewer's rate limit, and that budget is small enough to
101	+// run out mid-sweep (`budget.mjs`). So the order the reads happen in is not a
102	+// performance detail — it decides WHICH FACTS the page ends up holding when the money
103	+// stops.
104	+//
105	+// Read a member end to end before starting the next one, and the budget is spent
106	+// DEPTH-FIRST: the first members get their commit graphs and pack cards before the
107	+// last members have been looked at at all. The page that comes out of that says
108	+// "nothing is on fire" over a fleet it never finished reading, and the members it
109	+// never reached are the ones a viewer cannot tell from healthy.
110	+//
111	+// So a sweep here is HORIZONTAL. Every member is taken through one pass before any
112	+// member starts the next, cheapest and most load-bearing pass first: what a member IS,
113	+// then what needs a person's attention there, then the depth behind those numbers,
114	+// then decoration. Under pressure the page then loses the same panel everywhere
115	+// rather than losing whole members off the end of the list — a fleet missing its
116	+// graphs still answers "where do I need to look", and a fleet missing its tail does
117	+// not.
118	+//
119	+// The passes are also the natural paint boundaries: after pass two every row on the
120	+// page is ranked and every tile counts the whole roster, which is the moment the page
121	+// becomes the thing the viewer opened it for.
122	+
123	+// Members are read concurrently, but not all at once: a dozen members at several
124	+// calls each is enough parallel load to trip secondary rate limiting, and the page is
125	+// not in a hurry. Small and steady beats a burst that gets throttled.
126	+export const CONCURRENCY = 4;
127	+
128	+export async function pool(items, worker, limit = CONCURRENCY) {
129	+  const out = new Array(items.length);
130	+  let next = 0;
131	+  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
132	+    for (;;) {
133	+      const i = next; next += 1;
134	+      if (i >= items.length) return;
135	+      out[i] = await worker(items[i], i);
136	+    }
137	+  });
138	+  await Promise.all(runners);
139	+  return out;
140	+}
141	+
142	+// Run `phases` over `members`, one whole pass at a time.
143	+//
144	+// A phase is `{ id, label, run(member), appliesTo?(member) }`. `appliesTo` is how a
145	+// pass skips a member it has nothing to ask about — a repo that does not run
146	+// Claudinite, or one whose first read failed — and skipping is not the same as
147	+// failing: the member simply is not in that pass's population, and the pass's own
148	+// progress counts say so.
149	+//
150	+// `run` is called for its effect on the member; a phase that throws for one member
151	+// must not take the sweep down with it, so throwing is contained and reported through
152	+// `onAdvance` as that member's `error`. The pass continues, and so do the passes after
153	+// it — one member's unreadable tree is one row's missing column.
154	+export async function sweepPhases({ members, phases, limit = CONCURRENCY, onAdvance = null } = {}) {
155	+  for (const [index, phase] of phases.entries()) {
156	+    const targets = members.filter((m) => (phase.appliesTo ? phase.appliesTo(m) : true));
157	+    const total = targets.length;
158	+    let done = 0;
159	+    // A pass with nobody in it still announces itself: "no member had a tree to read"
160	+    // and "the tree pass has not started" are different states, and a progress line
161	+    // that skips silently makes them look identical.
162	+    if (!total) {
163	+      onAdvance?.({ phase: phase.id, label: phase.label, index, done: 0, total: 0, member: null, error: null });
164	+      continue;
