import json, sys

def truncate(s, n=500):
    if not isinstance(s, str):
        s = str(s)
    s = s.replace('\n', ' \\n ')
    if len(s) > n:
        return s[:n] + f'...[{len(s)}chars]'
    return s

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            t = d.get('type')
            ts = d.get('timestamp', '')
            if t == 'user':
                msg = d.get('message', {})
                content = msg.get('content')
                if isinstance(content, str):
                    print(f"[{ts}] USER-TEXT: {truncate(content, 800)}")
                elif isinstance(content, list):
                    for c in content:
                        if c.get('type') == 'tool_result':
                            err = c.get('is_error', False)
                            cc = c.get('content')
                            if isinstance(cc, list):
                                cc = ' '.join(x.get('text','') for x in cc if isinstance(x, dict))
                            print(f"[{ts}] TOOL_RESULT{'(ERROR)' if err else ''}: {truncate(cc, 400)}")
                        elif c.get('type') == 'text':
                            print(f"[{ts}] USER-TEXT: {truncate(c.get('text'), 800)}")
            elif t == 'assistant':
                msg = d.get('message', {})
                content = msg.get('content', [])
                usage = msg.get('usage', {})
                for c in content:
                    ct = c.get('type')
                    if ct == 'text':
                        print(f"[{ts}] ASSISTANT-TEXT: {truncate(c.get('text'), 800)}")
                    elif ct == 'tool_use':
                        name = c.get('name')
                        inp = c.get('input', {})
                        print(f"[{ts}] TOOL_USE: {name} {truncate(json.dumps(inp), 300)}")
            elif t == 'queue-operation':
                print(f"[{ts}] QUEUE-OP: {d.get('operation')} {truncate(d.get('content',''),300)}")
            # skip attachment, last-prompt, atis-latch by default

if __name__ == '__main__':
    main(sys.argv[1])

import json, sys

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def render(path):
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                print("PARSE ERROR", e)
                continue
            ts = obj.get("timestamp", "")
            typ = obj.get("type", obj.get("attachment", {}).get("type", "?"))
            role = None
            msg = obj.get("message")
            out = []
            out.append(f"[{ts}] type={typ}")
            if obj.get("attachment"):
                att = obj["attachment"]
                out.append(f"  attachment.type={att.get('type')} hook={att.get('hookName')}")
                if att.get("stdout"):
                    out.append(f"  stdout: {trunc(att.get('stdout'), 200)}")
            if msg:
                role = msg.get("role")
                content = msg.get("content")
                usage = msg.get("usage")
                if isinstance(content, str):
                    out.append(f"  {role}: {trunc(content, 500)}")
                elif isinstance(content, list):
                    for c in content:
                        ctype = c.get("type")
                        if ctype == "text":
                            out.append(f"  {role} text: {trunc(c.get('text'), 500)}")
                        elif ctype == "tool_use":
                            out.append(f"  {role} tool_use: {c.get('name')} input={trunc(json.dumps(c.get('input')), 300)}")
                        elif ctype == "tool_result":
                            cont = c.get("content")
                            out.append(f"  {role} tool_result: {trunc(cont, 300)}")
                        elif ctype == "thinking":
                            out.append(f"  {role} thinking: {trunc(c.get('thinking'), 300)}")
                        else:
                            out.append(f"  {role} {ctype}: {trunc(c, 200)}")
                if usage:
                    out.append(f"  usage: in={usage.get('input_tokens')} out={usage.get('output_tokens')} cache_read={usage.get('cache_read_input_tokens')} cache_creation={usage.get('cache_creation_input_tokens')}")
            print("\n".join(out))

if __name__ == "__main__":
    render(sys.argv[1])

