1	// The order a fleet sweep reads in. Pure: no clock, no I/O, no DOM — the callers
2	// supply what each pass does, this decides who it happens to and when.
3	//
4	// A fleet page is read on ONE viewer's rate limit, and that budget is small enough to
5	// run out mid-sweep (`budget.mjs`). So the order the reads happen in is not a
6	// performance detail — it decides WHICH FACTS the page ends up holding when the money
7	// stops.
8	//
9	// Read a member end to end before starting the next one, and the budget is spent
10	// DEPTH-FIRST: the first members get their commit graphs and pack cards before the
11	// last members have been looked at at all. The page that comes out of that says
12	// "nothing is on fire" over a fleet it never finished reading, and the members it
13	// never reached are the ones a viewer cannot tell from healthy.
14	//
15	// So a sweep here is HORIZONTAL. Every member is taken through one pass before any
16	// member starts the next, cheapest and most load-bearing pass first: what a member IS,
17	// then what needs a person's attention there, then the depth behind those numbers,
18	// then decoration. Under pressure the page then loses the same panel everywhere
19	// rather than losing whole members off the end of the list — a fleet missing its
20	// graphs still answers "where do I need to look", and a fleet missing its tail does
21	// not.
22	//
23	// The passes are also the natural paint boundaries: after pass two every row on the
24	// page is ranked and every tile counts the whole roster, which is the moment the page
25	// becomes the thing the viewer opened it for.
26	
27	// Members are read concurrently, but not all at once: a dozen members at several
28	// calls each is enough parallel load to trip secondary rate limiting, and the page is
29	// not in a hurry. Small and steady beats a burst that gets throttled.
30	export const CONCURRENCY = 4;
31	
32	export async function pool(items, worker, limit = CONCURRENCY) {
33	  const out = new Array(items.length);
34	  let next = 0;
35	  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
36	    for (;;) {
37	      const i = next; next += 1;
38	      if (i >= items.length) return;
39	      out[i] = await worker(items[i], i);
40	    }
41	  });
42	  await Promise.all(runners);
43	  return out;
44	}
45	
46	// Run `phases` over `members`, one whole pass at a time.
47	//
48	// A phase is `{ id, label, run(member), appliesTo?(member) }`. `appliesTo` is how a
49	// pass skips a member it has nothing to ask about — a repo that does not run
50	// Claudinite, or one whose first read failed — and skipping is not the same as
51	// failing: the member simply is not in that pass's population, and the pass's own
52	// progress counts say so.
53	//
54	// `run` is called for its effect on the member; a phase that throws for one member
55	// must not take the sweep down with it, so throwing is contained and reported through
56	// `onAdvance` as that member's `error`. The pass continues, and so do the passes after
57	// it — one member's unreadable tree is one row's missing column.
58	export async function sweepPhases({ members, phases, limit = CONCURRENCY, onAdvance = null } = {}) {
59	  for (const [index, phase] of phases.entries()) {
60	    const targets = members.filter((m) => (phase.appliesTo ? phase.appliesTo(m) : true));
61	    const total = targets.length;
62	    let done = 0;
63	    // A pass with nobody in it still announces itself: "no member had a tree to read"
64	    // and "the tree pass has not started" are different states, and a progress line
65	    // that skips silently makes them look identical.
66	    if (!total) {
67	      onAdvance?.({ phase: phase.id, label: phase.label, index, done: 0, total: 0, member: null, error: null });
68	      continue;
69	    }
70	    await pool(targets, async (member) => {
71	      let error = null;
72	      try {
73	        await phase.run(member);
74	      } catch (e) {
75	        error = e;
76	      }
77	      done += 1;
78	      onAdvance?.({ phase: phase.id, label: phase.label, index, done, total, member, error });
79	    }, limit);
80	  }
81	  return members;
82	}
83

1	// That a fleet sweep is HORIZONTAL, which is the whole point of `fleet-sweep.mjs`.
2	// The ordering is not a preference: the viewer's rate limit can run out mid-sweep, so
3	// a depth-first sweep spends it on the first members' decoration and leaves the last
4	// members unread — the one failure this module exists to prevent.
5	
6	import { test } from 'node:test';
7	import assert from 'node:assert/strict';
8	
9	import { sweepPhases } from '../fleet-sweep.mjs';
10	
11	const tick = () => new Promise((r) => setTimeout(r, 0));
12	
13	// A phase that records `<phase>:<repo>` when it finishes, after yielding — so a
14	// depth-first implementation has every opportunity to interleave and be caught.
15	const recorder = (log, id, opts = {}) => ({
16	  id,
17	  label: id,
18	  ...opts,
19	  run: async (m) => {
20	    await tick();
21	    log.push(`${id}:${m.repo}`);
22	  },
23	});
24	
25	const members = (...repos) => repos.map((repo, i) => ({ repo, i }));
26	
27	test('every member finishes a pass before any member starts the next', async () => {
28	  const log = [];
29	  const roster = members('o/a', 'o/b', 'o/c', 'o/d', 'o/e', 'o/f');
30	  await sweepPhases({
31	    members: roster,
32	    phases: [recorder(log, 'identity'), recorder(log, 'attention'), recorder(log, 'depth')],
33	    limit: 2,
34	  });
35	
36	  assert.equal(log.length, roster.length * 3);
37	  const phases = log.map((e) => e.split(':')[0]);
38	  assert.deepEqual(
39	    phases,
40	    [...Array(6).fill('identity'), ...Array(6).fill('attention'), ...Array(6).fill('depth')],
41	    'a pass may not begin while another member is still in the pass before it',
42	  );
43	});
44	
45	test('a pass reads only the members it applies to, and says so when that is none', async () => {
46	  const log = [];
47	  const seen = [];
48	  const roster = members('o/adopted', 'o/plain');
49	  await sweepPhases({
50	    members: roster,
51	    phases: [
52	      recorder(log, 'identity'),
53	      recorder(log, 'attention', { appliesTo: (m) => m.repo.endsWith('adopted') }),
54	      recorder(log, 'graphs', { appliesTo: () => false }),
55	    ],
56	    onAdvance: (a) => seen.push({ phase: a.phase, done: a.done, total: a.total, repo: a.member?.repo ?? null }),
57	  });
58	
59	  assert.deepEqual(log.filter((e) => e.startsWith('attention:')), ['attention:o/adopted']);
60	  // A pass with nobody in it still announces itself: "no member had one" and "the
61	  // pass has not started" must not look identical on the progress line.
62	  assert.deepEqual(seen.at(-1), { phase: 'graphs', done: 0, total: 0, repo: null });
63	  // The counts are the PASS's own population, never the roster's, so a progress line
64	  // built from them cannot claim members it was never going to read.
65	  assert.deepEqual(
66	    seen.filter((s) => s.phase === 'attention').map((s) => `${s.done}/${s.total}`),
67	    ['1/1'],
68	  );
69	});
70	
71	test('one member throwing does not take the pass, or the passes after it, down', async () => {
72	  const log = [];
73	  const errors = [];
74	  const roster = members('o/good', 'o/bad');
75	  await sweepPhases({
76	    members: roster,
77	    phases: [
78	      { id: 'depth', label: 'depth', run: async (m) => { if (m.repo === 'o/bad') throw new Error('403'); log.push(`depth:${m.repo}`); } },
79	      recorder(log, 'graphs'),
80	    ],
81	    onAdvance: (a) => { if (a.error) errors.push([a.phase, a.member.repo, a.error.message]); },
82	  });
83	
84	  assert.deepEqual(errors, [['depth', 'o/bad', '403']]);
85	  assert.deepEqual(log.filter((e) => e.startsWith('graphs:')).sort(), ['graphs:o/bad', 'graphs:o/good'],
86	    'the pass after the failure still reads the member whose earlier pass threw');
87	  assert.deepEqual(log.filter((e) => e.startsWith('depth:')), ['depth:o/good'], 'and the rest of that pass still ran');
88	});
89	
90	test('a pass runs no more than `limit` members at once', async () => {
91	  let live = 0;
92	  let peak = 0;
93	  await sweepPhases({
94	    members: members('o/a', 'o/b', 'o/c', 'o/d', 'o/e'),
95	    phases: [{
96	      id: 'identity',
97	      label: 'identity',
98	      run: async () => { live += 1; peak = Math.max(peak, live); await tick(); live -= 1; },
99	    }],
100	    limit: 2,
101	  });
102	  assert.equal(peak, 2, 'a burst wide enough to trip secondary rate limiting is the thing being avoided');
103	});
104

