// The canon home repo's OWN local pack — Claudinite-specific working rules and
// lessons that are NOT portable to consumers (those belong in packs/, the shared
// canon). This is the capture surface the growth-extract scheduled task routes the
// canon's own non-portable lessons into — from repo activity and from captured
// conversations alike; a lesson that turns out to travel becomes a PR against
// packs/ instead.
//
// Discovered like any local pack — the canon's own runner passes
// discoverPacks({ localRoot: <repo root> }), so this is scanned alongside the
// canon packs/ tree — and active because .claudinite-settings.json declares it. Its
// id must equal its directory name ("claudinite") and may not shadow a canon pack.
export default {
  ruleRoutingGuidance: {
    belongs: 'working rules and lessons specific to developing Claudinite itself and not portable to any consumer',
    excludes: 'fleet-facing curation duties and policing of the packs/ tree — that is the canon-curation local pack',
  },
  // home-seeded-packs-declared rides beside these as a declared check
  // (declared-checks.json in this directory).
};
---declared-checks---
[
  {
    "id": "pack-independence",
    "severity": "blocking",
    "failureMessage": "the vendor set ships a pack only when declared, so a cross-pack import crashes every consumer that vendors one pack without the other",
    "fix": "declare the dependency (requires) and pass configuration, move the shared helper into engine/checks/helpers, or accept the import with a reason in .claudinite-settings.json",
    "relevantWhen": { "pathExists": "packs" },
    "forbidReferences": [
      {
        "siblings": "packs",
        "to": "*",
        "scope": "imports",
        "allow": ["engine", "packs/claudinite-tasks/shared-code"],
        "reason": "a pack imports only its own files, the engine surface, and the tasks pack's published shared-code/ — abilities otherwise cross pack boundaries through declaration and configuration, never imports; a pack's updates/ is carved out because no vendor set carries it, so an import there cannot crash a consumer (#1317)",
    "except": ["packs/claudinite-lifecycle/updates"]
      }
    ]
  }
]

